# Extract Bash commands, normalize them for pattern analysis
while IFS= read -r f; do
  jq -r 'select(.type=="assistant") | .message.content[]? | select(.type=="tool_use") | select(.name=="Bash") | .input.command' "$f" 2>/dev/null
done < /tmp/transcript_files.txt | \
# Extract leading command + first arg
awk '{
  # Remove leading env vars (FOO=bar)
  while ($1 ~ /^[A-Z_]+=/) { $0 = substr($0, length($1)+2) }
  # Take first two tokens
  n = split($0, a, " ")
  if (a[1] == "cd") {
    # cd "path" && cmd → take cmd after &&
    for (i=1; i<=n; i++) if (a[i] == "&&") { print a[i+1] " " a[i+2]; break }
  } else {
    print a[1] " " a[2]
  }
}' | sort | uniq -c | sort -rn | head -40

